let bad=0, ex=[];
for (let d=0; d<100; d++) { const r=d/100;
 for (const [b,bi] of [[0,100],[0.05,95]]) for (let s=1; s<=20000; s++) {
  const f=Math.floor(s*(1-r)*(1-b)); const e=Math.floor(s*(100-d)*bi/10000);
  const g=Math.floor(Math.round(s*(1-r)*(1-b)*1e6)/1e6);
  if (f!==e){bad++; if(ex.length<5) ex.push([s,r,b,s*(1-r)*(1-b),e]);}
  if (g!==e) console.log("guard mismatch",s,r,b);
 }}
