git checkout -q -b fix/issue-12-double-discount && cat > src/cart.js <<'EOF'
// Cart total in yen. `discount` is the customer's discount rate (0.1 = 10%).
// Carts with 10 or more lines get an extra 5% bulk discount, applied once
// after the customer discount. Fractions of a yen are dropped.
export function total(items, discount = 0) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= 10 ? 0.05 : 0;
  const discounted = subtotal * (1 - discount) * (1 - bulk);
  // Snap to 1e-6 before flooring so float error (2150 * 0.94 gives
  // 2020.9999999999998) does not cost a whole yen.
  return Math.floor(Math.round(discounted * 1e6) / 1e6);
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}
EOF
cat > tests/cart.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});

test('customer discount is applied once', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
  assert.equal(total(lines(9, 1000), 0.1), 8100);
});

test('bulk discount is applied once, after the customer discount', () => {
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

test('bulk discount alone is 5%', () => {
  assert.equal(total(lines(10, 1000)), 9500);
});

test('fractions of a yen are dropped', () => {
  assert.equal(total(lines(10, 11)), 104); // 110 * 0.95 = 104.5
  assert.equal(total([{ price: 999, qty: 1 }], 0.1), 899); // 899.1
  assert.equal(total(lines(10, 30), 0.1), 256); // 300 * 0.9 * 0.95 = 256.5
});

test('float error does not drop a whole yen', () => {
  assert.equal(total([{ price: 2150, qty: 1 }], 0.06), 2021); // 2020.9999999999998 in floats
  assert.equal(total([{ price: 8550, qty: 1 }], 0.06), 8037);
});
EOF
